@GameTestHolder("slavicmyths_bayun") @PrefixGameTestTemplate(false)
public final class BayunGameTests {
    private static final class Connection extends net.minecraft.network.Connection {
        private final io.netty.channel.embedded.EmbeddedChannel channel=new io.netty.channel.embedded.EmbeddedChannel();
        Connection(){super(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);}
        @Override public io.netty.channel.Channel channel(){return channel;}
    }
    private static final class Listener extends net.minecraft.server.network.ServerGamePacketListenerImpl {
        Listener(ServerPlayer p){super(p.getServer(),new Connection(),p,net.minecraft.server.network.CommonListenerCookie.createInitial(p.getGameProfile(),false));}
        @Override public void send(net.minecraft.network.protocol.Packet<?> packet){}
        @Override public void send(net.minecraft.network.protocol.Packet<?> packet,net.minecraft.network.PacketSendListener listener){}
    }
    @SuppressWarnings("unchecked") private static Map<UUID,ServerPlayer> online(ServerPlayer p){try{var f=net.minecraft.server.players.PlayerList.class.getDeclaredField("playersByUUID");f.setAccessible(true);return (Map<UUID,ServerPlayer>)f.get(p.server.getPlayerList());}catch(Exception e){throw new RuntimeException(e);}}
    private static ServerPlayer player(GameTestHelper t,String name){var w=t.getLevel();var p=new ServerPlayer(w.getServer(),w,new com.mojang.authlib.GameProfile(UUID.randomUUID(),name),ClientInformation.createDefault());p.connection=new Listener(p);p.setGameMode(GameType.SURVIVAL);p.setNoGravity(true);p.moveTo(t.absoluteVec(new Vec3(12,2,12)));p.setOnGround(true);w.addNewPlayer(p);online(p).put(p.getUUID(),p);return p;}
    private static void cleanup(ServerPlayer... players){for(var p:players){online(p).remove(p.getUUID());p.discard();}}
    private static BayunEntity cat(GameTestHelper t){for(int x=2;x<30;x++)for(int z=2;z<30;z++)t.setBlock(new BlockPos(x,1,z),Blocks.STONE);var c=BayunContent.ENTITY.get().create(t.getLevel());c.moveTo(t.absoluteVec(new Vec3(12,2,10.7)));c.home=c.blockPosition();t.getLevel().addFreshEntity(c);return c;}
    @GameTest(template="empty",timeoutTicks=30) public static void deliveryAndSparseKnowledge(GameTestHelper t){var p=player(t,"NewBook");TaleService.deliver(p);t.assertTrue(p.getInventory().countItem(ModItems.LORE_BOOK.get())==1,"First book missing");TaleService.deliver(p);t.assertTrue(p.getInventory().countItem(ModItems.LORE_BOOK.get())==1,"Duplicate book");p.getInventory().clearContent();TaleService.deliver(p);t.assertTrue(p.getInventory().countItem(ModItems.LORE_BOOK.get())==0,"Lost book reissued");var d=TaleData.get(t.getLevel());t.assertTrue(d.player(p.getUUID()).getCompound("Entries").isEmpty(),"Catalogue auto-awarded discoveries");t.assertTrue(TaleCatalog.entries().size()==217,"Catalogue count");TaleService.promote(p,"slavicmyths:kot_bayun",3,false);TaleService.promote(p,"slavicmyths:kot_bayun",1,false);t.assertTrue(d.stage(p.getUUID(),"slavicmyths:kot_bayun")==3,"Knowledge regressed");t.assertTrue(!d.player(p.getUUID()).getCompound("Entries").getCompound("slavicmyths:kot_bayun").getBoolean("Defeated"),"Interaction fabricated victory");cleanup(p);System.out.println("BAYUN_BOOK_DELIVERY_PASS new=1 duplicate=0 lossReissue=0 monotonic=true");t.succeed();}
    @GameTest(template="empty",timeoutTicks=30) public static void pendingInventoryAndLegacy(GameTestHelper t){var p=player(t,"FullBook");for(int i=0;i<36;i++)p.getInventory().setItem(i,new ItemStack(Items.COBBLESTONE,64));TaleService.deliver(p);t.assertTrue(TaleData.get(t.getLevel()).player(p.getUUID()).getString("Delivery").equals("PENDING"),"Full inventory delivery lost");p.getInventory().setItem(7,ItemStack.EMPTY);TaleService.deliver(p);TaleService.deliver(p);t.assertTrue(p.getInventory().countItem(ModItems.LORE_BOOK.get())==1,"Pending delivery not exactly once");var old=player(t,"LegacyBook");old.getInventory().add(new ItemStack(ModItems.LORE_BOOK.get()));TaleService.deliver(old);t.assertTrue(old.getInventory().countItem(ModItems.LORE_BOOK.get())==1&&TaleData.get(t.getLevel()).player(old.getUUID()).getBoolean("LegacyDelivery"),"Legacy duplicate");cleanup(p,old);t.succeed();}
    @GameTest(template="empty",timeoutTicks=30) public static void milkFishAndPersonalTrust(GameTestHelper t){var c=cat(t);var a=player(t,"MilkGift");var b=player(t,"FishGift");a.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.DIRT,3));c.interact(a,InteractionHand.MAIN_HAND);t.assertTrue(a.getMainHandItem().getCount()==3&&c.trust(a)==0,"Wrong gift consumed or rewarded");a.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.MILK_BUCKET));c.interact(a,InteractionHand.MAIN_HAND);t.assertTrue(c.trust(a)==25&&a.getInventory().countItem(Items.BUCKET)==1&&a.getInventory().countItem(Items.MILK_BUCKET)==0,"Milk/trust/bucket");t.assertTrue(c.trust(b)==0,"Shared player trust");a.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.COD,2));c.interact(a,InteractionHand.MAIN_HAND);t.assertTrue(a.getMainHandItem().getCount()==2&&c.trust(a)==25,"Gift cooldown consumed");b.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.SALMON,2));c.interact(b,InteractionHand.MAIN_HAND);t.assertTrue(c.trust(b)==23&&b.getMainHandItem().getCount()==1&&c.canTalk(b),"First fish not safe");t.assertTrue(c.canTalk(a),"Milk not safe");b.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);b.setShiftKeyDown(true);c.interact(b,InteractionHand.MAIN_HAND);c.interact(b,InteractionHand.MAIN_HAND);t.assertTrue(c.trust(b)==27,"Pet repeated or rejected");var saved=new CompoundTag();c.addAdditionalSaveData(saved);c.readAdditionalSaveData(saved);t.assertTrue(c.trust(a)==25&&c.trust(b)==27,"Saved personal bonds lost");cleanup(a,b);c.discard();System.out.println("BAYUN_GIFTS_PASS milk25 fish23 petOnce4 separate=true cooldown=true");t.succeed();}
    @GameTest(template="empty",timeoutTicks=30) public static void readonlyBridgeAndRealGraph(GameTestHelper t){var p=player(t,"BookGraph");var data=org.slavicmyths.yaga.YagaData.get(t.getLevel());int before=data.players.size();var snapshot=TaleService.snapshot(p);t.assertTrue(data.players.size()==before,"Book created Yaga progress");t.assertTrue(snapshot.getCompound("Recipes").size()==487,"Real recipes missing");for(var id:snapshot.getCompound("Recipes").getAllKeys())t.assertTrue(com.google.gson.JsonParser.parseString(snapshot.getCompound("Recipes").getString(id)).getAsJsonObject().has("type"),"Invalid loaded recipe");var seen=new HashSet<String>();for(var raw:snapshot.getList("Advancements",10)){var n=(CompoundTag)raw;t.assertTrue(seen.add(n.getString("Id")),"Duplicate advancement node");var holder=p.server.getAdvancements().get(net.minecraft.resources.ResourceLocation.parse(n.getString("Id")));t.assertTrue(holder!=null&&n.getBoolean("Done")==p.getAdvancements().getOrStartProgress(holder).isDone(),"Forged graph progress");}t.assertTrue(seen.contains("slavicmyths:meet_bayun")&&seen.contains("slavicmyths:group_legends"),"Real new graph missing");var wire=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),p.registryAccess());TaleNetwork.Snapshot.CODEC.encode(wire,new TaleNetwork.Snapshot(snapshot,true,true));int payload=wire.readableBytes();t.assertTrue(payload<900000,"Book snapshot exceeds payload budget");var decoded=TaleNetwork.Snapshot.CODEC.decode(wire);t.assertTrue(decoded.data().equals(snapshot),"Snapshot codec changed data");wire.release();System.out.println("BAYUN_WIRE_PASS bytes="+payload+" actualCodecRoundtrip=true NOT_MULTIPLAYER_TEST");long start=System.nanoTime();for(int i=0;i<100;i++)TaleService.snapshot(p);double millis=(System.nanoTime()-start)/1_000_000.;System.out.println("BAYUN_SNAPSHOT_MEASURE total100Ms="+millis+" averageMs="+(millis/100)+" catalogue="+snapshot.getList("Catalog",10).size()+" NOT_CLIENT_LATENCY");cleanup(p);t.succeed();}
    @GameTest(template="empty",timeoutTicks=380) public static void physicalDangerAndGrace(GameTestHelper t){var c=cat(t);var p=player(t,"PounceTarget");t.runAtTickTime(150,()->{t.assertTrue(p.isAlive(),"Killed before grace");t.assertTrue(!c.clip().equals("hypnosis_song")&&!c.clip().equals("pounce_kill"),"Early dangerous animation");});t.runAtTickTime(220,()->t.assertTrue(p.isAlive()&&!c.clip().equals("pounce_kill"),"Early pounce"));t.runAtTickTime(320,()->{System.out.println("BAYUN_POUNCE_OBSERVATION alive="+p.isAlive()+" catPos="+c.position()+" playerPos="+p.position()+" clip="+c.clip());t.assertTrue(!p.isAlive(),"Physical close pounce never hit");cleanup(p);c.discard();t.succeed();});}
    @GameTest(template="empty",timeoutTicks=370) public static void creativeAndRetreatCancellation(GameTestHelper t){var c=cat(t);var p=player(t,"RetreatTarget");t.runAtTickTime(245,()->{p.moveTo(c.getX()+30,p.getY(),c.getZ());});t.runAtTickTime(290,()->{t.assertTrue(p.isAlive(),"Remote retreat kill");p.setGameMode(GameType.CREATIVE);p.moveTo(c.getX(),c.getY(),c.getZ()+1);});t.runAtTickTime(350,()->{t.assertTrue(p.isAlive(),"Creative killed");cleanup(p);c.discard();t.succeed();});}
    @GameTest(template="empty",timeoutTicks=30) public static void hintAndStateRoundtrip(GameTestHelper t){var c=cat(t);var p=player(t,"SavedBook");TaleService.promote(p,"slavicmyths:kot_bayun",4,false);TaleService.hint(p,"slavicmyths:kot_bayun",p.level().dimension().location().toString(),c.getUUID(),c.home);var hint=TaleService.snapshot(p).getCompound("Hints").getCompound("slavicmyths:kot_bayun");double dist=Math.hypot(hint.getDouble("X")-c.home.getX(),hint.getDouble("Z")-c.home.getZ());t.assertTrue(dist>=25&&dist<=80&&hint.getInt("Radius")==250&&!hint.hasUUID("Target")&&!hint.contains("Anchor"),"Exact coordinates or private target exposed");var data=TaleData.get(t.getLevel());var copy=TaleData.load(data.save(new CompoundTag(),t.getLevel().registryAccess()),t.getLevel().registryAccess());t.assertTrue(copy.stage(p.getUUID(),"slavicmyths:kot_bayun")==4,"Saved knowledge lost");c.setPos(c.home.getX()+400,c.home.getY(),c.home.getZ());t.assertTrue(TaleService.snapshot(p).getCompound("Hints").getCompound("slavicmyths:kot_bayun").getBoolean("Stale"),"Moved target not stale");data.player(p.getUUID()).getCompound("Hints").getCompound("slavicmyths:kot_bayun").putLong("Expires",-1);t.assertTrue(TaleService.snapshot(p).getCompound("Hints").getCompound("slavicmyths:kot_bayun").getBoolean("Stale"),"Expired hint not stale");cleanup(p);c.discard();System.out.println("BAYUN_STATE_PASS NBT_ROUNDTRIP_NOT_RELOG=true hintOffset="+dist);t.succeed();}
    @GameTest(template="empty",timeoutTicks=30) public static void nookValidationAndDeduplication(GameTestHelper t){for(int x=12;x<=24;x++)for(int z=12;z<=24;z++){t.setBlock(new BlockPos(x,2,z),Blocks.GRASS_BLOCK);for(int y=3;y<=24;y++)t.setBlock(new BlockPos(x,y,z),Blocks.AIR);}var center=t.absolutePos(new BlockPos(18,3,18));t.setBlock(new BlockPos(18,3,18),Blocks.WATER);t.assertTrue(!BayunFeature.place(t.getLevel(),center),"Wet site accepted");t.assertTrue(t.getLevel().getBlockState(center.below()).is(Blocks.GRASS_BLOCK),"Rejected site partially written");t.setBlock(new BlockPos(18,3,18),Blocks.AIR);t.setBlock(new BlockPos(18,7,18),Blocks.GRASS_BLOCK);t.assertTrue(!BayunFeature.place(t.getLevel(),center),"Steep site accepted");t.setBlock(new BlockPos(18,7,18),Blocks.AIR);diagnoseNook(t,center);t.assertTrue(BayunFeature.place(t.getLevel(),center),"Valid flat nook rejected");var cats=t.getLevel().getEntitiesOfClass(BayunEntity.class,new net.minecraft.world.phys.AABB(center).inflate(8));t.assertTrue(cats.size()==1,"Nook cat count");var duplicate=BayunContent.ENTITY.get().create(t.getLevel());duplicate.home=center;duplicate.moveTo(Vec3.atBottomCenterOf(center));t.assertTrue(!t.getLevel().addFreshEntity(duplicate),"Duplicate home resident accepted");t.assertTrue(!BayunFeature.place(t.getLevel(),center),"Existing nook rewritten");for(int direction:new int[]{-1,1})for(int x=-1;x<=1;x++)t.assertTrue(t.getLevel().getBlockState(center.offset(x,0,direction*3)).isAir(),"Three-wide exit blocked");for(var c:cats)c.discard();System.out.println("BAYUN_NOOK_PASS wetRejected=true steepRejected=true noPartialWrite=true flat=true duplicateBlocked=true exits3=true");t.succeed();}
    private static void diagnoseNook(GameTestHelper t,BlockPos source){var w=t.getLevel();var center=w.getHeightmapPos(net.minecraft.world.level.levelgen.Heightmap.Types.MOTION_BLOCKING_NO_LEAVES,source);int y=center.getY();System.out.println("BAYUN_NOOK_DIAGNOSTIC center="+center);for(int x=-6;x<=6;x++)for(int z=-6;z<=6;z++){var p=center.offset(x,0,z);int h=w.getHeight(net.minecraft.world.level.levelgen.Heightmap.Types.MOTION_BLOCKING_NO_LEAVES,p.getX(),p.getZ());var ground=w.getBlockState(new BlockPos(p.getX(),h-1,p.getZ()));if(Math.abs(h-y)>2||!w.hasChunkAt(p)||!ground.is(net.minecraft.tags.BlockTags.DIRT)&&!ground.is(Blocks.STONE)&&!ground.is(Blocks.MOSS_BLOCK))System.out.println("BAYUN_NOOK_REJECT ground="+ground+" pos="+p+" h="+h+" loaded="+w.hasChunkAt(p));for(int dy=0;dy<=3;dy++){var state=w.getBlockState(p.above(dy));if(!state.isAir()&&!state.canBeReplaced()&&!state.is(net.minecraft.tags.BlockTags.LEAVES))System.out.println("BAYUN_NOOK_REJECT obstacle="+state+" pos="+p.above(dy));}}}
    @GameTest(template="empty",timeoutTicks=360) public static void blockedLineOfSightCancels(GameTestHelper t){var c=cat(t);var p=player(t,"WallTarget");t.runAtTickTime(245,()->{for(int x=10;x<=14;x++)for(int y=2;y<=5;y++)t.setBlock(new BlockPos(x,y,11),Blocks.STONE);});t.runAtTickTime(340,()->{t.assertTrue(p.isAlive(),"Killed through solid wall");t.assertTrue(!c.clip().equals("pounce_kill"),"Continued blocked pounce");cleanup(p);c.discard();t.succeed();});}
    @GameTest(template="empty",timeoutTicks=370) public static void giftDuringWarning(GameTestHelper t){var c=cat(t);var p=player(t,"WarningGift");t.runAtTickTime(220,()->{t.assertTrue(c.clip().equals("threat_warn"),"Warning not reached");p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.COD,2));c.interact(p,InteractionHand.MAIN_HAND);t.assertTrue(p.getMainHandItem().getCount()==1&&c.trust(p)==23&&c.canTalk(p),"Warning gift not accepted");});t.runAtTickTime(340,()->{t.assertTrue(p.isAlive()&&c.canTalk(p),"Warning gift did not cancel danger");cleanup(p);c.discard();t.succeed();});}
    @GameTest(template="empty",timeoutTicks=370) public static void physicalMissDoesNotAutokill(GameTestHelper t){var c=cat(t);var p=player(t,"DodgePounce");boolean[] dodged={false};t.onEachTick(()->{if(!dodged[0]&&c.clip().equals("pounce_kill")&&c.age(0)>=9){p.moveTo(c.getX()+5.5,p.getY(),c.getZ());dodged[0]=true;}});t.runAtTickTime(340,()->{t.assertTrue(dodged[0],"No physical pounce observed");t.assertTrue(p.isAlive(),"Miss became remote auto-kill");t.assertTrue(!c.clip().equals("pounce_kill"),"Miss never recovered");cleanup(p);c.discard();System.out.println("BAYUN_DODGE_PASS actualPounce=true actualMiss=true remoteKill=false");t.succeed();});}
    @GameTest(template="empty",timeoutTicks=370) public static void independentVisitors(GameTestHelper t){var c=cat(t);var a=player(t,"SafeVisitor");var b=player(t,"UnsafeVisitor");a.moveTo(c.getX()-2,c.getY(),c.getZ());a.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.MILK_BUCKET));c.interact(a,InteractionHand.MAIN_HAND);t.runAtTickTime(330,()->{t.assertTrue(a.isAlive()&&c.trust(a)==25,"Another visitor changed safe player");t.assertTrue(!b.isAlive()&&c.trust(b)==0,"Gift protected unrelated visitor");cleanup(a,b);c.discard();t.succeed();});}
    @GameTest(template="empty",timeoutTicks=30) public static void dialogueForgeryAndFutureData(GameTestHelper t){var c=cat(t);var p=player(t,"TalkAuthority");p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.COD));c.interact(p,InteractionHand.MAIN_HAND);BayunNetwork.open(p,c);var n=p.getPersistentData();UUID token=n.getUUID("BayunMenu");BayunNetwork.choose(p,new BayunNetwork.Choice(c.getId(),UUID.randomUUID(),1,2));t.assertTrue(TaleData.get(t.getLevel()).player(p.getUUID()).getCompound("Hints").isEmpty(),"Forged nonce granted hint");BayunNetwork.choose(p,new BayunNetwork.Choice(c.getId(),token,1,2));t.assertTrue(TaleData.get(t.getLevel()).player(p.getUUID()).getCompound("Hints").contains("slavicmyths:kot_bayun"),"Valid choice not functional");BayunNetwork.choose(p,new BayunNetwork.Choice(c.getId(),token,1,0));t.assertTrue(n.getInt("BayunMenuSequence")==1,"Replay accepted");CompoundTag future=new CompoundTag();future.putInt("Version",99);future.putString("Unknown","keep me");var d=TaleData.load(future,t.getLevel().registryAccess());t.assertTrue(!d.compatible()&&!d.promote(p.getUUID(),"slavicmyths:kot_bayun",4,t.getLevel().getGameTime(),true)&&d.save(new CompoundTag(),t.getLevel().registryAccess()).equals(future),"Future schema overwritten");cleanup(p);c.discard();t.succeed();}
    @GameTest(template="empty",timeoutTicks=40) public static void immunityAndSpectator(GameTestHelper t){var c=cat(t);var p=player(t,"SpectatorSafe");p.setGameMode(GameType.SPECTATOR);var d=t.getLevel().damageSources();for(var source:List.of(d.playerAttack(p),d.inFire(),d.lava(),d.drown(),d.explosion(null,null),d.fellOutOfWorld()))t.assertTrue(!c.hurt(source,1000)&&c.isAlive()&&c.getHealth()==100,"Bayun damaged by "+source.getMsgId());c.setRemainingFireTicks(80);c.setAirSupply(0);t.runAtTickTime(12,()->{t.assertTrue(!c.isOnFire()&&c.getAirSupply()==c.getMaxAirSupply(),"Fire or air not restored");t.assertTrue(p.isAlive()&&TaleData.get(t.getLevel()).stage(p.getUUID(),"slavicmyths:kot_bayun")==0,"Spectator entered danger encounter");cleanup(p);c.kill();t.assertTrue(c.isRemoved(),"Admin cleanup failed");System.out.println("BAYUN_IMMUNITY_PASS sword=true fire=true lava=true drowning=true explosion=true void=true spectator=true");t.succeed();});}
}
